from rdkit import Chem
from rdkit.Chem import Draw, rdMolDescriptors
cands = {
 'p1': "CC1=C[C@@H]([C@@]2([C@H]([C@H]3[C@@](C)([C@H]4[C@H]([C@@]3([C@H](C2=O)O)C4(C)C)O)O)CO)O)C1",
