}
for name,s in cands.items():
    m = Chem.MolFromSmiles(s)
    print(name, 'parse', m is not None, end=' ')
    if m:
        print(rdMolDescriptors.CalcMolFormula(m), 'atoms', m.GetNumAtoms())
